body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen,
    Ubuntu, Cantarell, sans-serif;
  background-color: #f5f5f5;
  color: #333;
  height: 100vh;
}

.container {
  max-width: 640px;
  margin: 0 auto;
  padding: 2rem 1rem;
  display: flex;
  flex-direction: column;
  height: 100vh;
}

h1 {
  text-align: center;
  margin-bottom: 1.5rem;
  font-size: 1.5rem;
  color: #222;
}

#message-form {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}

#message-input {
  flex: 1;
  padding: 0.6rem 0.8rem;
  font-size: 1rem;
  border: 1px solid #ccc;
  border-radius: 6px;
  outline: none;
  transition: border-color 0.2s;
}

#message-input:focus {
  border-color: #4a90d9;
}

#message-form button {
  padding: 0.6rem 1.2rem;
  font-size: 1rem;
  background-color: #4a90d9;
  color: #fff;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s;
}

#message-form button:hover {
  background-color: #357abd;
}

#message-list {
  flex: 1;
  overflow-y: auto;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #fff;
  padding: 0.5rem;
}

.message-item {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid #eee;
}

.message-item:last-child {
  border-bottom: none;
}

.message-text {
  display: block;
  font-size: 0.95rem;
  word-break: break-word;
}

.message-time {
  display: block;
  color: #999;
  font-size: 0.75rem;
  margin-top: 0.25rem;
}
