{"path": "/tmp/runs/smokes/qwen-moe-q4/message-board/no_verification/runs/101/app/server.js", "content": "const express = require('express');
const cors = require('cors');
const path = require('path');
const fs = require('fs');
const { PGlite } = require('@electric-sql/pglite');

const app = express();
const PORT = 3001;

// Middleware
app.use(cors());
app.use(express.json());

// PGLite data directory
const DATA_DIR = path.join(__dirname, 'pglite-data');
if (!fs.existsSync(DATA_DIR)) {
  fs.mkdirSync(DATA_DIR, { recursive: true });
}

const DB_PATH = path.join(DATA_DIR, 'messages.db');

let db;
const sseClients = [];

// Initialize database
async function initDB() {
  db = await PGlite.create({
    dataDir: DB_PATH,
  });

  await db.exec(`
    CREATE TABLE IF NOT EXISTS messages (
      id SERIAL PRIMARY KEY,
      text TEXT NOT NULL,
      created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
    );
  `);

  console.log('Database initialized.');
}

// GET /api/messages - Fetch all messages
app.get('/api/messages', async (req, res) => {
  try {
    const result = await db.query(
      'SELECT id, text, created_at FROM messages ORDER BY created_at ASC'
    );
    res.json(result.rows);
  } catch (err) {
    console.error('Error fetching messages:', err);
    res.status(500).json({ error: 'Failed to fetch messages' });
  }
});

// POST /api/messages - Insert a new message and broadcast via SSE
app.post('/api/messages', async (req, res) => {
  const { text } = req.body;

  if (!text || typeof text !== 'string') {
    return res.status(400).json({ error: 'Text is required' });
  }

  try {
    const result = await db.query(
      "INSERT INTO messages (text) VALUES ($1) RETURNING id, text, created_at",
      [text]
    );
    const message = result.rows[0];

    // Broadcast to all SSE clients
    const data = JSON.stringify(message);
    sseClients.forEach((client) => {
      client.write(`data: ${data}\n\n`);
    });

    res.json(message);
  } catch (err) {
    console.error('Error inserting message:', err);
    res.status(500).json({ error: 'Failed to insert message' });
  }
});

// GET /api/stream - SSE endpoint for real-time updates
app.get('/api/stream', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.flushHeaders();

  sseClients.push(res);

  req.on('close', () => {
    const index = sseClients.indexOf(res);
    if (index !== -1) {
      sseClients.splice(index, 1);
    }
  });
});

// Start server
async function start() {
  try {
    await initDB();
    app.listen(PORT, () => {
      console.log(`Backend server running on http://localhost:${PORT}`);
    });
  } catch (err) {
    console.error('Failed to start server:', err);
    process.exit(1);
  }
}

start();
"}

{"content": "import './style.css';

const messageForm = document.getElementById('message-form');
const messageInput = document.getElementById('message-input');
const messageList = document.getElementById('message-list');

// Fetch initial messages from the server
async function loadMessages() {
  try {
    const res = await fetch('/api/messages');
    const messages = await res.json();
    messages.forEach((msg) => appendMessage(msg));
  } catch (err) {
    console.error('Failed to load messages:', err);
  }
}

// Append a single message to the DOM
function appendMessage(msg) {
  const div = document.createElement('div');
  div.classList.add('message-item');
  div.dataset.id = msg.id;

  const textSpan = document.createElement('span');
  textSpan.classList.add('message-text');
  textSpan.textContent = msg.text;

  const timeSpan = document.createElement('small');
  timeSpan.classList.add('message-time');
  timeSpan.textContent = new Date(msg.created_at).toLocaleTimeString();

  div.appendChild(textSpan);
  div.appendChild(timeSpan);
  messageList.appendChild(div);

  // Scroll to bottom
  messageList.scrollTop = messageList.scrollHeight;
}

// Post a new message via HTTP POST
async function postMessage(text) {
  try {
    const res = await fetch('/api/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text }),
    });
    if (!res.ok) throw new Error('Failed to post message');
  } catch (err) {
    console.error('Failed to post message:', err);
  }
}

// Connect to SSE stream for real-time updates
function connectStream() {
  const eventSource = new EventSource('/api/stream');

  eventSource.addEventListener('message', (event) => {
    try {
      const msg = JSON.parse(event.data);
      appendMessage(msg);
    } catch (err) {
      console.error('Failed to parse SSE message:', err);
    }
  });

  eventSource.onerror = () => {
    console.warn('SSE connection lost. Reconnecting...');
    eventSource.close();
